contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address adr) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (0));
        uint beforeBalance = address(c).balance;
        c.multiplicate{value: 0}(adr); if (__ESBMC_reverted()) return;
        assert(address(c).balance == beforeBalance);
    }
    receive() external payable {}
}

